import unittest
from candidate import fruit_distribution

class TestFruitDistribution(unittest.TestCase):
    def test_normal_case_apples_and_oranges(self):
        self.assertEqual(fruit_distribution("5 apples and 6 oranges", 19), 8)

    def test_normal_case_zero_apples(self):
        self.assertEqual(fruit_distribution("0 apples and 1 oranges", 3), 2)

    def test_normal_case_large_numbers(self):
        self.assertEqual(fruit_distribution("2 apples and 3 oranges", 100), 95)

    def test_normal_case_extreme_apples(self):
        self.assertEqual(fruit_distribution("100 apples and 1 oranges", 120), 19)

    def test_empty_string(self):
        with self.assertRaises(ValueError):
            fruit_distribution("", 10)

    def test_invalid_string_format(self):
        with self.assertRaises(ValueError):
            fruit_distribution("5 apples and oranges", 10)

    def test_non_integer_total_fruits(self):
        with self.assertRaises(TypeError):
            fruit_distribution("5 apples and 6 oranges", "19")

    def test_non_integer_numbers_in_string(self):
        with self.assertRaises(ValueError):
            fruit_distribution("five apples and 6 oranges", 10)

    def test_multiple_spaces_in_string(self):
        self.assertEqual(fruit_distribution("5  apples  and  6  oranges", 19), 8)

    def test_case_sensitivity(self):
        self.assertEqual(fruit_distribution("5 APPLES and 6 ORANGES", 19), 8)

    def test_partial_string_matching(self):
        self.assertEqual(fruit_distribution("5 apples and 6 oranges", 19), 8)

    def test_whitespace_around_numbers(self):
        self.assertEqual(fruit_distribution(" 5  apples  and  6  oranges  ", 19), 8)

    def test_single_digit_numbers(self):
        self.assertEqual(fruit_distribution("1 apples and 2 oranges", 10), 7)

    def test_zero_oranges(self):
        self.assertEqual(fruit_distribution("5 apples and 0 oranges", 10), 5)

    def test_zero_apples(self):
        self.assertEqual(fruit_distribution("0 apples and 6 oranges", 10), 4)

    def test_negative_numbers_in_string(self):
        with self.assertRaises(ValueError):
            fruit_distribution("5 apples and -6 oranges", 10)

    def test_non_numeric_string(self):
        with self.assertRaises(ValueError):
            fruit_distribution("five apples and six oranges", 10)

    def test_non_integer_total_fruits_with_string(self):
        with self.assertRaises(TypeError):
            fruit_distribution("5 apples and 6 oranges", "19")

    def test_mixed_case_numbers(self):
        self.assertEqual(fruit_distribution("5 apples and 6 ORANGES", 19), 8)

    def test_extra_whitespace(self):
        self.assertEqual(fruit_distribution("5  apples  and  6  oranges  ", 19), 8)

if __name__ == '__main__':
    unittest.main()
